const std = @import("std");
const model = @import("model.zig");
const c = @import("generated/compatibility.zig");
const Numeric = struct { json: []const u8, value: ?u64 = null, err: ?anyerror = null };
const String = struct { json: []const u8, value: ?[]const u8 = null, err: ?anyerror = null };

// Handwritten input/expected pairs; no fixture is generated by the implementation.
const profiles = [_]Numeric{
    .{ .json = "{}" },                                                           .{ .json = "{\"id\":null}" },                                         .{ .json = "{\"ID\":null}" },
    .{ .json = "{\"id\":0}", .value = 0 },                                       .{ .json = "{\"ID\":1}", .value = 1 },                                .{ .json = "{\"id\":9007199254740993}", .value = 9007199254740993 },
    .{ .json = "{\"id\":18446744073709551615}", .value = 18446744073709551615 }, .{ .json = "{\"id\":1e3}", .value = 1000 },                           .{ .json = "{\"ID\":1000e-3}", .value = 1 },
    .{ .json = "{\"id\":1.0}", .value = 1 },                                     .{ .json = "{\"id\":-0}", .value = 0 },                               .{ .json = "{\"id\":-1}", .err = error.OutOfRange },
    .{ .json = "{\"id\":18446744073709551616}", .err = error.OutOfRange },       .{ .json = "{\"id\":1.5}", .err = error.NonIntegral },                .{ .json = "{\"id\":\"1\"}", .err = error.InvalidType },
    .{ .json = "{\"id\":false}", .err = error.InvalidType },                     .{ .json = "{\"id\":[]}", .err = error.InvalidType },                 .{ .json = "{\"id\":1,\"ID\":1}", .err = error.AliasCollision },
    .{ .json = "{\"ID\":null,\"id\":0}", .err = error.AliasCollision },          .{ .json = "{\"id\":7,\"unmodeled\":9007199254740993}", .value = 7 },
};
const strings = [_]String{
    .{ .json = "{}" },                                                                   .{ .json = "{\"storage_capacity\":null}" },
    .{ .json = "{\"storage_capacity\":\"\"}", .value = "" },                             .{ .json = "{\"storage_capacity\":\"Unlimited\"}", .value = "Unlimited" },
    .{ .json = "{\"storage_capacity\":0}", .value = "0" },                               .{ .json = "{\"storage_capacity\":-1}", .value = "-1" },
    .{ .json = "{\"storage_capacity\":9007199254740993}", .value = "9007199254740993" }, .{ .json = "{\"storage_capacity\":1e3}", .value = "1e3" },
    .{ .json = "{\"storage_capacity\":true}", .value = "true" },                         .{ .json = "{\"storage_capacity\":false}", .value = "false" },
    .{ .json = "{\"storage_capacity\":[]}", .err = error.InvalidType },                  .{ .json = "{\"storage_capacity\":{}}", .err = error.InvalidType },
};
const positions = [_]String{
    .{ .json = "{}" },                                                                   .{ .json = "{\"position\":null}" },
    .{ .json = "{\"position\":\"Director\"}", .value = "Director" },                     .{ .json = "{\"position\":\"\"}", .value = "" },
    .{ .json = "{\"position\":{\"name\":\"Manager\"}}", .value = "Manager" },            .{ .json = "{\"position\":{\"name\":null}}" },
    .{ .json = "{\"position\":{\"name\":\"Employee\",\"id\":1}}", .value = "Employee" }, .{ .json = "{\"position\":2}", .value = "2" },
    .{ .json = "{\"position\":true}", .value = "true" },                                 .{ .json = "{\"position\":{}}", .err = error.MissingField },
    .{ .json = "{\"position\":[]}", .err = error.InvalidType },                          .{ .json = "{\"position\":{\"name\":[]}}", .err = error.InvalidType },
};
const rewards = [_]Numeric{
    .{ .json = "{}" },                                       .{ .json = "{\"amount\":null}" },                                        .{ .json = "{\"quantity\":null}" },
    .{ .json = "{\"amount\":0}", .value = 0 },               .{ .json = "{\"quantity\":1}", .value = 1 },                             .{ .json = "{\"amount\":2}", .value = 2 },
    .{ .json = "{\"quantity\":1e2}", .value = 100 },         .{ .json = "{\"amount\":9007199254740993}", .value = 9007199254740993 }, .{ .json = "{\"amount\":1,\"quantity\":1}", .err = error.AliasCollision },
    .{ .json = "{\"amount\":-1}", .err = error.OutOfRange }, .{ .json = "{\"quantity\":\"1\"}", .err = error.InvalidType },           .{ .json = "{\"amount\":false}", .err = error.InvalidType },
};
const Union = struct { kind: enum { competition, employment }, json: []const u8, branch: usize };
const unions = [_]Union{
    .{ .kind = .competition, .json = "{\"name\":\"Halloween\",\"treats_collected\":7}", .branch = 0 },
    .{ .kind = .competition, .json = "{\"name\":\"Easter Egg Hunt\",\"score\":8}", .branch = 1 },
    .{ .kind = .competition, .json = "{\"name\":\"Easter\",\"total\":9}", .branch = 1 },
    .{ .kind = .competition, .json = "{\"name\":\"Rock, Paper, Scissors\"}", .branch = 2 },
    .{ .kind = .competition, .json = "{\"name\":\"Elimination\",\"attacks\":1}", .branch = 3 },
    .{ .kind = .competition, .json = "{\"name\":\"FutureCompetition\",\"future\":1}", .branch = 4 },
    .{ .kind = .competition, .json = "{}", .branch = 4 },
    .{ .kind = .employment, .json = "{\"type\":\"job\",\"name\":\"Army\"}", .branch = 0 },
    .{ .kind = .employment, .json = "{\"type\":\"company\",\"id\":3}", .branch = 1 },
    .{ .kind = .employment, .json = "{\"type\":\"future\",\"unknown\":true}", .branch = 2 },
    .{ .kind = .employment, .json = "{\"type\":\"company\",\"rating\":0}", .branch = 1 },
    .{ .kind = .employment, .json = "{}", .branch = 2 },
};
const News = struct { json: []const u8, count: usize = 0, key: ?[]const u8 = null, value: ?[]const u8 = null, err: ?anyerror = null };
const news = [_]News{
    .{ .json = "{}" },                                                                                   .{ .json = "{\"news\":null}" },
    .{ .json = "{\"news\":{}}" },                                                                        .{ .json = "{\"news\":[]}" },
    .{ .json = "{\"news\":{\"a\":\"Hello\"}}", .count = 1, .key = "a", .value = "Hello" },               .{ .json = "{\"news\":{\"b\":{\"news\":\"World\",\"timestamp\":1}}}", .count = 1, .key = "b", .value = "World" },
    .{ .json = "{\"news\":[{\"id\":7,\"news\":\"Array\"}]}", .count = 1, .key = "7", .value = "Array" }, .{ .json = "{\"news\":false}", .err = error.InvalidType },
};
fn checkString(expected: ?[]const u8, actual: ?[]const u8) !void {
    if (expected) |s| try std.testing.expectEqualStrings(s, actual orelse return error.TestUnexpectedResult) else try std.testing.expect(actual == null);
}

test "76 handwritten compatibility scenarios with typed values and selected branches" {
    const a = std.testing.allocator;
    for (profiles) |case| {
        if (case.err) |err| {
            try std.testing.expectError(err, model.decode(c.CompanyProfile, a, case.json));
            continue;
        }
        var r = try model.decode(c.CompanyProfile, a, case.json);
        defer r.deinit();
        try std.testing.expectEqual(case.value, r.value.id);
    }
    for (strings) |case| {
        if (case.err) |err| {
            try std.testing.expectError(err, model.decode(c.CompanyUpgrades, a, case.json));
            continue;
        }
        var r = try model.decode(c.CompanyUpgrades, a, case.json);
        defer r.deinit();
        try checkString(case.value, r.value.storage_capacity);
    }
    for (positions) |case| {
        if (case.err) |err| {
            try std.testing.expectError(err, model.decode(c.CompanyEmployee, a, case.json));
            continue;
        }
        var r = try model.decode(c.CompanyEmployee, a, case.json);
        defer r.deinit();
        try checkString(case.value, r.value.position);
    }
    for (rewards) |case| {
        if (case.err) |err| {
            try std.testing.expectError(err, model.decode(c.UserCrimeRewardItem, a, case.json));
            continue;
        }
        var r = try model.decode(c.UserCrimeRewardItem, a, case.json);
        defer r.deinit();
        try std.testing.expectEqual(case.value, r.value.amount);
    }
    for (unions) |case| switch (case.kind) {
        .competition => {
            var r = try model.decode(c.UserCompetition, a, case.json);
            defer r.deinit();
            try std.testing.expectEqual(case.branch, @backingInt(std.meta.activeTag(r.value)));
        },
        .employment => {
            var r = try model.decode(c.UserEmployment, a, case.json);
            defer r.deinit();
            try std.testing.expectEqual(case.branch, @backingInt(std.meta.activeTag(r.value)));
        },
    };
    for (news) |case| {
        if (case.err) |err| {
            try std.testing.expectError(err, model.decode(c.CompanyNewsBundle, a, case.json));
            continue;
        }
        var r = try model.decode(c.CompanyNewsBundle, a, case.json);
        defer r.deinit();
        try std.testing.expectEqual(case.count, r.value.news.entries.len);
        if (case.key) |key| try checkString(case.value, (r.value.news.get(key) orelse return error.TestUnexpectedResult).news);
    }
    try std.testing.expectEqual(76, profiles.len + strings.len + positions.len + rewards.len + unions.len + news.len);
}

test "flattened extras preserve exact raw values and aliases are excluded" {
    var r = try model.decode(c.CompanyProfile, std.testing.allocator, "{\"ID\":1,\"future\":9007199254740993,\"nil\":null,\"off\":false}");
    defer r.deinit();
    try std.testing.expect(r.value.extra.get("ID") == null);
    try std.testing.expectEqualStrings("9007199254740993", r.value.extra.get("future").?.number_string);
    try std.testing.expect(r.value.extra.get("nil").? == .null);
    try std.testing.expect(!r.value.extra.get("off").?.bool);
}

test "union field access stays within the selected public branch" {
    const a = std.testing.allocator;
    var easter = try model.decode(c.UserCompetition, a, "{\"name\":\"Easter Egg Hunt\",\"score\":8}");
    defer easter.deinit();
    try std.testing.expectEqual(@as(?u64, 8), easter.value.v1.score);
    var job = try model.decode(c.UserEmployment, a, "{\"type\":\"company\",\"id\":3}");
    defer job.deinit();
    try std.testing.expectEqual(@as(?u64, 3), job.value.v1.id);
    var unknown = try model.decode(c.UserCompetition, a, "{\"name\":\"Future\",\"new_score\":9007199254740993}");
    defer unknown.deinit();
    try std.testing.expectEqualStrings("9007199254740993", unknown.value.v4.extra.get("new_score").?.number_string);
    const created: c.UserTradeTimestamp = .{ .v1 = 42 };
    try std.testing.expectEqual(@as(u64, 42), created.v1);
}
fn allocationScenario(a: std.mem.Allocator) !void {
    var r = try model.decode(c.CompanyNewsBundle, a, "{\"news\":[{\"id\":7,\"news\":\"News\",\"future\":true}],\"unknown\":null}");
    defer r.deinit();
    try std.testing.expectEqualStrings("News", r.value.news.get("7").?.news.?);
    try std.testing.expect(r.value.extra.get("unknown").? == .null);
}
test "systematic allocation failures in compatibility normalization and extras" {
    try std.testing.checkAllAllocationFailures(std.testing.allocator, allocationScenario, .{});
}

test "typed mutations serialize canonical alias keys and retained unknown fields" {
    const a = std.testing.allocator;
    var r = try model.decode(c.CompanyProfile, a, "{\"ID\":1,\"future\":9007199254740993}");
    defer r.deinit();
    r.value.id = 2;
    const bytes = try r.toJson(a);
    defer a.free(bytes);
    var parsed = try std.json.parseFromSlice(model.Raw, a, bytes, .{ .parse_numbers = false });
    defer parsed.deinit();
    try std.testing.expect(parsed.value.object.get("ID") == null);
    try std.testing.expectEqualStrings("2", parsed.value.object.get("id").?.number_string);
    try std.testing.expectEqualStrings("9007199254740993", parsed.value.object.get("future").?.number_string);
    var again = try model.decode(c.CompanyProfile, a, bytes);
    defer again.deinit();
    try std.testing.expectEqual(@as(?u64, 2), again.value.id);
}
test "union serialization emits its payload and presence omits absent fields" {
    const a = std.testing.allocator;
    const value: c.UserTradeTimestamp = .{ .v1 = 9007199254740993 };
    const bytes = try model.stringify(a, value);
    defer a.free(bytes);
    try std.testing.expectEqualStrings("9007199254740993", bytes);
    const T = struct { missing: model.Presence(u64) = .absent, nil: model.Presence(u64) = .null, number: model.Presence(u64) = .{ .value = 0 } };
    const fields = try model.stringify(a, T{});
    defer a.free(fields);
    try std.testing.expectEqualStrings("{\"nil\":null,\"number\":0}", fields);
}

test "all trade discriminators and unknown variants roundtrip selected payloads" {
    const fixtures = .{
        .{ "{\"type\":\"Money\",\"details\":{\"amount\":5}}", @as(usize, 0), "Money" },
        .{ "{\"type\":\"Item\",\"details\":{}}", @as(usize, 1), "Item" },
        .{ "{\"type\":\"Faction\",\"details\":{}}", @as(usize, 2), "Faction" },
        .{ "{\"type\":\"Company\",\"details\":{}}", @as(usize, 3), "Company" },
        .{ "{\"type\":\"Property\",\"details\":{}}", @as(usize, 4), "Property" },
        .{ "{\"type\":\"NAP\",\"details\":{}}", @as(usize, 5), "NAP" },
        .{ "{\"type\":\"Future\",\"details\":{\"unknown\":true}}", @as(usize, 6), "Future" },
    };
    inline for (fixtures) |case| {
        var r = try model.decode(c.TradeItem, std.testing.allocator, case[0]);
        defer r.deinit();
        try std.testing.expectEqual(case[1], @backingInt(std.meta.activeTag(r.value)));
        const bytes = try r.toJson(std.testing.allocator);
        defer std.testing.allocator.free(bytes);
        var raw = try std.json.parseFromSlice(model.Raw, std.testing.allocator, bytes, .{});
        defer raw.deinit();
        try std.testing.expectEqualStrings(case[2], raw.value.object.get("type").?.string);
        try std.testing.expect(raw.value.object.get("extra") == null);
        var again = try model.decode(c.TradeItem, std.testing.allocator, bytes);
        defer again.deinit();
        try std.testing.expectEqual(case[1], @backingInt(std.meta.activeTag(again.value)));
    }
}
